#include<bits/stdc++.h>
#include<atcoder/modint>
using namespace std;
using mint = atcoder::modint998244353;

int main(){
  string s;
  cin >> s;
  map<char, mint>dp;
  for(char c: s){
    dp[c] = dp['a'] + dp['b'] + dp['c'] + 1;
  }

  mint ans = 0;
  for(auto[k, v]: dp){
    ans += v;
  }
  cout << ans.val() << endl;
}
